// ============================================
// مسار التنبيهات (Notifications)
// ============================================
router.get('/notifications', async (_req, res) => {
  try {
    const notifications: any[] = [];
    const today = new Date().toISOString().split('T')[0];
    const now = new Date();
    const in7Days = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
    const in30Days = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

    // 1. الجلسات القادمة
    const sessions = await CaseSession.find({ sessionDate: { $gte: today } })
      .populate('caseId', 'caseNumber caseYear')
      .populate('courtId', 'name')
      .sort({ sessionDate: 1 });

    for (const s of sessions) {
      let urgency: 'high' | 'medium' | 'low' = 'low';
      if (s.sessionDate <= in7Days) urgency = 'high';
      else if (s.sessionDate <= in30Days) urgency = 'medium';

      notifications.push({
        id: s._id.toString(),
        type: 'session',
        title: `جلسة محكمة - ${(s.caseId as any)?.caseNumber || ''}`,
        description: s.subject || '',
        date: s.sessionDate,
        caseNumber: (s.caseId as any)?.caseNumber,
        courtName: (s.courtId as any)?.name,
        urgency,
      });
    }

    // 2. الإعلانات بدون استلام وبجلسة قادمة
    const announcements = await CaseAnnouncement.find({
      receiptDate: { $in: ['', null] },
      sessionDate: { $gte: today, $ne: '' },
    })
      .populate('caseId', 'caseNumber caseYear')
      .populate('courtId', 'name')
      .sort({ sessionDate: 1 });

    for (const a of announcements) {
      notifications.push({
        id: a._id.toString(),
        type: 'announcement',
        title: `إعلان قانوني - ${(a.caseId as any)?.caseNumber || ''}`,
        description: a.subject || '',
        date: a.sessionDate || '',
        caseNumber: (a.caseId as any)?.caseNumber,
        courtName: (a.courtId as any)?.name,
        urgency: 'high',
      });
    }

    res.json({ success: true, data: notifications });
  } catch (err) { res.status(500).json({ success: false, message: (err as Error).message }); }
});

